from fastapi import APIRouter, Body, Depends

from modules.agentCompanySettings import (
    agentCompanySettings_sp, all_agentCompanySettings_sp, one_agentCompanySettings_sp,
)
from security.session_tokens import require_company_rows_or_platform_admin

# Generated by posgmo-factory (PRD tests/prd_agentCompanySetting.json); guards added by hand.
# Write: admin/manager of that company (or SmartLoans admin). List: staff of that company.
# One: same, or X-Worker-Key — LoanAgents_SmartLoans reads it by companyId + agentKey.
_ADMIN_ROLES = {"admin", "manager"}
_STAFF_ROLES = {"admin", "manager", "employee", "business"}
_write_guard = require_company_rows_or_platform_admin("agentCompanySettings", _ADMIN_ROLES, allow_worker_key=False)
_list_guard = require_company_rows_or_platform_admin("agentCompanySettings", _STAFF_ROLES, allow_worker_key=False)
_one_guard = require_company_rows_or_platform_admin("agentCompanySettings", _STAFF_ROLES, allow_worker_key=True)

router = APIRouter()

with open("./docs_description/agentCompanySettings.txt", "r", encoding="utf-8") as file:
    agentCompanySettings_docstring = file.read()
with open("./docs_description/agentCompanySettings_all.txt", "r", encoding="utf-8") as file:
    agentCompanySettings_all_docstring = file.read()
with open("./docs_description/agentCompanySettings_one.txt", "r", encoding="utf-8") as file:
    agentCompanySettings_one_docstring = file.read()


@router.post("/agentCompanySettings", summary="agentCompanySettings: upsert one company's settings for an agent",
             description=agentCompanySettings_docstring)
def agentCompanySettings(json_file: dict = Body(...), claims: dict | None = Depends(_write_guard)):
    rows = json_file.get("agentCompanySettings") or [{}]
    # Who saved it comes from the signed token, never from the body.
    rows[0]["updatedByUserId"] = int(claims["sub"]) if claims and str(claims.get("sub", "")).isdigit() else None
    return agentCompanySettings_sp(json_file)


@router.post("/all_agentCompanySettings", summary="all agentCompanySettings of a company",
             description=agentCompanySettings_all_docstring, dependencies=[Depends(_list_guard)])
def all_agentCompanySettings(json_file: dict = Body(...)):
    return all_agentCompanySettings_sp(json_file)


@router.post("/one_agentCompanySettings", summary="one agentCompanySetting (companyId + agentKey)",
             description=agentCompanySettings_one_docstring, dependencies=[Depends(_one_guard)])
def one_agentCompanySettings(json_file: dict = Body(...)):
    return one_agentCompanySettings_sp(json_file)
